function classifyUseCase(project) {
  if (project.category === 'Artcraft, Design & Creative Media') return 'Creative';
  const text = `${project.name} ${project.description} ${project.tags.join(' ')}`;
  if (
    project.category === 'AI & Machine Learning' &&
    /\b(comfyui|diffusers|whisper|image-gen|diffusion|tts|speech|audio|3d|vision|yolo|opencv)\b/i.test(text)
  ) {
    return 'Creative';
  }
  if (
    (project.category === 'Open-Source Software Clones & Alternatives' ||
      project.category === 'Productivity & Collaboration') &&
    /\b(excalidraw|tldraw|immich|pixelfed|peertube|owncast|jellyfin|navidrome|penpot|figma|miro)\b/i.test(text)
  ) {
    return 'Creative';
  }
  if (project.category === 'Reverse Engineering & Binary Analysis') {
    return 'Educational';
  }
  if (
    project.category === 'AI & Machine Learning' &&
    /\b(pytorch|scikit-learn|jax|keras|xgboost|lightgbm|catboost|litgpt|transformers|gradio|streamlit|deep-learning|data-science|research|scientific)\b/i.test(text)
  ) {
    return 'Educational';
  }
  if (
    /\b(education|educational|learning|research|notebook|jupyter|marimo|course|science|scientific|math|algorithm|reversing|reverse-engineering|decompiler|disassembler|ctf|forensics|anki|flashcard|wiki|bookstack|paper|dataset|tutorial)\b/i.test(
      text
    )
  ) {
    return 'Educational';
  }
  if (
    project.category === 'CMS & E-Commerce' ||
    project.category === 'Analytics & Monitoring' ||
    project.category === 'Cybersecurity & Privacy' ||
    project.category === 'Productivity & Collaboration' ||
    project.category === 'Open-Source Software Clones & Alternatives'
  ) {
    return 'Enterprise';
  }
  return 'Developer';
}

const PRIORITY_RANK = {
  Creative: 1,
  Enterprise: 2,
  Educational: 3,
  Developer: 4,
};

async function generateCatalog() {
  const allProjects = [];
  const usedIds = new Set();

  // Start date for deterministic featuredDate assignment
  const baseDateUtc = Date.UTC(2026, 9, 17); // 2026-10-17
  let dayOffset = 0;

  for (const [category, tuples] of Object.entries(CATALOG_BY_CATEGORY)) {
    for (const tuple of tuples) {
      const [slug, name, description, language, license, stars, tags, websiteUrl, quickStart] = tuple;
      const cleanSlug = slug.trim();
      let baseId =
        cleanSlug.split('/')[1]?.toLowerCase().replace(/[^a-z0-9]+/g, '-') ||
        name.toLowerCase().replace(/[^a-z0-9]+/g, '-');
      if (usedIds.has(baseId)) {
        baseId = cleanSlug.toLowerCase().replace(/[^a-z0-9]+/g, '-');
      }
      usedIds.add(baseId);

      const rawGithubUrl = cleanSlug.startsWith('http')
        ? cleanSlug
        : `https://github.com/${cleanSlug}`;
      const githubUrl = rawGithubUrl.split('#')[0];
      const cleanWebsiteUrl = (websiteUrl || githubUrl).split('#')[0];

      const dt = new Date(baseDateUtc - (dayOffset % 90) * 86400000);
      const featuredDate = dt.toISOString().split('T')[0];
      dayOffset++;

      const proj = {
        id: baseId,
        name,
        description,
        category,
        tags,
        githubUrl,
        websiteUrl: cleanWebsiteUrl,
        featuredDate,
        stars,
        language,
        license,
        quickStart: quickStart || `git clone ${githubUrl}.git`,
      };
      proj.useCase = classifyUseCase(proj);
      allProjects.push(proj);
    }
  }

  allProjects.sort((a, b) => {
    const rankDiff = (PRIORITY_RANK[a.useCase] || 4) - (PRIORITY_RANK[b.useCase] || 4);
    if (rankDiff !== 0) return rankDiff;
    return (b.stars || 0) - (a.stars || 0);
  });

  await fs.writeFile(OUT_PATH, JSON.stringify(allProjects, null, 2) + '\n', 'utf8');
  console.log(`Generated ${allProjects.length} curated open-source repositories in ${OUT_PATH}`);
}

generateCatalog().catch((err) => {
  console.error(err);
  process.exit(1);
});
